import math


def _extended_gcd(p, q):
    '''Return (g, x, y) with p * x + q * y == g for non-negative p and q.'''
    old_r, r = p, q
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r:
        quotient = old_r // r
        old_r, r = r, old_r - quotient * r
        old_s, s = s, old_s - quotient * s
        old_t, t = t, old_t - quotient * t
    return old_r, old_s, old_t


def _ceil_div(p, q):
    '''Return the ceiling of p / q for a non-zero q.'''
    return -((-p) // q)


def _non_negative_solution_for_mixed_signs(a, b, n):
    '''Return the non-negative solution with the smallest x, if one exists.'''
    g = math.gcd(a, b)
    if n % g != 0:
        return None
    _, x_abs, y_abs = _extended_gcd(abs(a), abs(b))
    scale = n // g
    x_particular = (1 if a > 0 else -1) * x_abs * scale
    y_particular = (1 if b > 0 else -1) * y_abs * scale
