    return ('x = ', x, ', y = ', y)


def solution(a, b, n):
    '''Find non-negative integers x and y satisfying a * x + b * y == n.

    Return ('x = ', x, ', y = ', y), choosing the smallest such x.
    Return None if no non-negative integer pair satisfies the equation.
    '''
    if a == 0 and b == 0:
        return ('x = ', 0, ', y = ', 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return ('x = ', 0, ', y = ', n // b)
        return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return ('x = ', n // a, ', y = ', 0)
        return None
